   SUBROUTINE mp_win_create_lv(base, comm, win)
      INTEGER(KIND=int_8), DIMENSION(:), INTENT(INOUT), CONTIGUOUS   :: base
      TYPE(mp_comm_type), INTENT(IN) :: comm
