                      msglen, MPI_DOUBLE_PRECISION, root, comm%handle, ierr)
      IF (ierr /= 0) CALL mp_stop(ierr, "mpi_gather @ "//routineN)
      CALL add_perf(perf_id=4, count=1, msg_size=msglen*real_8_size)
