      MARK_USED(recvcount)
      MARK_USED(root)
      MARK_USED(comm)
      msg(1:recvcount) = msg_scatter(1 + displs(1):1 + displs(1) + sendcounts(1))
      request = mp_request_null
#endif
      CALL mp_timestop(handle)
   END SUBROUTINE mp_iscatterv_rv

