                      msglen, MPI_DOUBLE_COMPLEX, root, comm%handle, ierr)
      IF (ierr /= 0) CALL mp_stop(ierr, "mpi_gather @ "//routineN)
      CALL add_perf(perf_id=4, count=1, msg_size=msglen*(2*real_8_size))
#else
      MARK_USED(root)
