      COMPLEX(kind=real_4), INTENT(INOUT)                   :: msg(:)
      INTEGER, INTENT(IN)                      :: root
      CLASS(mp_comm_type), INTENT(IN) :: comm
      TYPE(mp_request_type), INTENT(OUT)                   :: request

