      COMPLEX(kind=real_4), INTENT(IN)                      :: msg
      COMPLEX(kind=real_4), CONTIGUOUS, INTENT(OUT)                     :: msg_gather(:)
      INTEGER, INTENT(IN)                      :: root
      CLASS(mp_comm_type), INTENT(IN) :: comm

