                       recvbuf, recvcounts, displs, MPI_COMPLEX, &
                       root, comm%handle, ierr)
      IF (ierr /= 0) CALL mp_stop(ierr, "mpi_gatherv @ "//routineN)
      CALL add_perf(perf_id=4, &
                    count=1, &
                    msg_size=sendcount*(2*real_4_size))
#else
